function nextId(machineId) {
  const ts = Date.now();          // no check that ts moved forward
  seq = (seq + 1) & 0xfff;        // 12-bit sequence, wraps silently
  return (BigInt(ts) << 22n) | (BigInt(machineId) << 12n) | BigInt(seq);
