// 41-bit ms timestamp | 10-bit machineId | 12-bit sequence
let sequence = 0;
function makeId() {
  const ts = Date.now();
  const machineId = Math.floor(Math.random() * 1024);   // pick a machine id
  sequence = (sequence + 1) % 4096;                     // 12-bit sequence
  return (BigInt(ts) << 22n)
       | (BigInt(machineId) << 12n)
       | BigInt(sequence);
}
